import React, { useState, useRef } from 'react';

function IntroOverlay({ onComplete }) {
  const [started, setStarted] = useState(false);
  const [showMessage, setShowMessage] = useState(false);
  const [fadeOut, setFadeOut] = useState(false);
  const audioRefs = useRef({
    sound1: new Audio('/assets/audio/sound1.mp3'),
    sound2: new Audio('/assets/audio/sound2.mp3')
  });

  const startSequence = async () => {
    setStarted(true);
    try {
      // Play sound1 and wait for it to end
      await new Promise((resolve) => {
        audioRefs.current.sound1.onended = resolve;
        audioRefs.current.sound1.play();
      });
      // Show message and play sound2 simultaneously
      setShowMessage(true);
      audioRefs.current.sound2.play();
      await new Promise((resolve) => {
        audioRefs.current.sound2.onended = resolve;
      });
      // Start fade out
      setFadeOut(true);
      await new Promise(resolve => setTimeout(resolve, 1000));
      onComplete();
    } catch (error) {
      console.error('Error playing audio:', error);
      onComplete();
    }
  };

  React.useEffect(() => {
    return () => {
      // Cleanup audio on unmount
      Object.values(audioRefs.current).forEach(audio => {
        audio.pause();
        audio.currentTime = 0;
      });
    };
  }, []);

  return (
    <div className={`fixed inset-0 bg-black z-50 flex items-center justify-center transition-opacity duration-1000 ${fadeOut ? 'opacity-0' : 'opacity-100'}`}>
      {!started ? (
        <button
          className="bg-gray-800 text-white px-8 py-4 rounded-lg text-2xl shadow-lg hover:bg-gray-700 transition-all duration-300 transform hover:scale-105"
          onClick={startSequence}
        >
          เริ่มต้น
        </button>
      ) : (
        <div className={`text-center transition-all duration-1000 ${showMessage ? 'opacity-100 scale-100' : 'opacity-0 scale-95'}`}>
          <h2 className="text-4xl font-bold text-white mb-4 animate-fade-in">
            ชีวิตสั้นกว่าที่คิด...
          </h2>
          <p className="text-2xl text-gray-300 animate-fade-in-delay">
            วางแผนวันสุดท้ายไว้ก่อนดีไหม?
          </p>
        </div>
      )}
    </div>
  );
}

export default IntroOverlay;
